local S = {}

S.guides = {
    { name = 'About this data', group = 'Server', desc = 'Explains which parts of the server\'s wiki fed this data, how it was condensed, and what is missing. Source: https://ffxi-legendary.com/robots.txt, https://ffxi-legendary.com/search/search_index.json', steps = { { title = 'What was fetched', note = '• Origin: the server\'s MkDocs wiki at https://ffxi-legendary.com, read on 2026-10-28.\n• robots.txt had no Disallow rules or content signals, so no page was skipped.\n• Bulk files used: /assets/gear-data.json (built 2026-09-23T10:15:37) and /assets/item-search-data.json (built 2026-10-03T11:17:09).\n• 26 wiki pages were read: changelog, changes (plus background-systems), economy (crafted-gear, home-point), getting-started (first-steps, leveling, progression-guide, your-session), progression (augmenting-guide, cross-job-abilities, cross-job-traits, death-penalty, prime-trials, reforge, server-features, spell-mastery, subjob-exp, weapon-forge, weapon-journey, weapon-pilgrimage), reference (commands, gear-vs-retail, travel-and-warps, ws-vs-retail), rules.' }, { title = 'How it was turned into this guide', note = '• Gear entries come from gear-data.json items that have a source or drop, merged with sources from item-search-data.json.\n• Each server-note step covers one section of a wiki page.\n• Quest-style guides follow the site\'s getting-started and progression walkthroughs, one step per section.\n• Very long sections were trimmed; the wiki page holds the full text.' }, { title = 'Not covered', note = '• No crafting recipes or skill-up ranges, since the site publishes none.\n• No retail missions or story quests; use standard guides for those.\n• Gear with no listed source is omitted.\n• Endgame content pages, spell lists and leaderboards are not summarised.\n• Values shift with updates; the wiki is the final authority.' } } },
    { name = 'Rates and progression', group = 'Server', desc = 'Summary of Legendary\'s rate changes, starting perks, custom systems, subjob EXP sharing and the Escha ZiTah death penalty. Source: https://ffxi-legendary.com/changes/, https://ffxi-legendary.com/progression/subjob-exp/, https://ffxi-legendary.com/progression/death-penalty/', steps = { { title = 'Rates', note = '• 3×: EXP (mob kills and scripted sources such as FoV/GoV and ROE), Capacity Points (kills and scripted), Sparks, FoV Tabs.\n• 1× (retail): drop rate, mob gil, quest gil, quest Bayld, fame, combat/magic skill-ups, TP gain for players, pets, Trusts and Fellows, NPC shop prices.\n• Crafting: 10× skill-up rate, 2× HQ chance.\n• Trusts/Fellows: 2× max HP and MP, 1.5× base stats, take 15% damage from enemy AoE spells not aimed at them.\n• Death costs no EXP.' }, { title = 'New character bonuses', note = '• 300,000 gil (retail 10).\n• Inventory and satchel at 80 (max).\n• All 8 Mog Wardrobes at 80 slots from creation.\n• Level cap 99 from the start, no Limit Break.\n• Subjob and advanced jobs available immediately.\n• All maps and all outpost warps (Tu\'Lia and Tavnazia included) granted; opening cutscene skipped.\n• Weapon skills, spells, key items, missions, maps and a starter gear kit are granted automatically.' }, { title = 'Combat and magic', note = '• Cure, elemental, divine, ninjutsu, blue magic, dark drain, weapon skill and potion/ether potency are all 1× (retail).\n• Stoneskin cap 10,000 (retail 350); the formula (Enhancing skill + MND) is unchanged, so typical endgame casts absorb about 700–1,200.\n• Blink: 10 shadows (retail 2). Aquaveil: 10 hits (retail 1).\n• Spikes last 1800s (retail 180s); elemental debuffs 1200s (retail 120s).' }, { title = 'Movement', note = '• Base run speed 150 (retail 50); gear speed cap 250 (retail 80); mount speed 200 (retail 80).\n• The Legendary Ring\'s +25% movement counts inside the cap.' }, { title = 'Merits and currencies', note = '• Merit points held: 30 (same as retail).\n• Caps: Sparks 999,999; Accolades 999,999; Valor 500,000; Ballista crystals 20,000.\n• No weekly Sparks/Accolades spending limit.' }, { title = 'Dynamis', note = '• No cooldown between runs; minimum level 1.\n• Prismatic Hourglass given at creation.\n• Currency exchange 10:1 (retail 100:1); 100s to 1s exchange enabled.\n• COP Dynamis needs no Chains of Promathia progress (FREE_COP_DYNAMIS = 0).' }, { title = 'Trusts', note = '• Custom Engagement is on.\n• Alter Ego Extravaganza (acquisition discounts) and Alter Ego Expo (HPP / MPP / status resistance bonus) are running.' }, { title = 'Quality-of-life settings', note = '• @unstuck command, 24h cooldown.\n• Unlimited AH listings (retail 7).\n• Gear can be equipped from Mog Satchel / Sack / Case with a client addon.\n• Explorer Moogle from level 10; ROE timed records, Synergy and Login Campaign active.\n• Gobbie Mystery Box tally: 50 points/day, eligible from day 0.\n• ENM key-item cooldown 120h; REGIME_REWARD_THRESHOLD = 15.\n• EXP rings: multiple allowed, no weekly limit, up to 10 Divine Might earrings.\n• Homepoint teleport enabled.' }, { title = 'Custom NPCs and hubs', note = '• Escha ZiTah: Hunt Hub (rank, marks, rank unlocks, reward shop), Hunt Spawner (pops current-rank NMs), Armor Vendor and Weapons Vendor (Bronze / Silver / Gold gear for three seal currencies).\n• Hunting League: 5 ranks, about 3 NMs per rank, paid in marks.\n• Reforge (!reforged): spawners for Sky Gods, Unity NMs or Abyssea NMs; each kill gives a base AF/Relic/Empyrean piece plus track marks; Reforge Vendor upgrades base to +1, +2, +3; all jobs supported.\n• Purgonorgo Isle hub (!hub, also !leaf and !lib): home point, Warpman, Gil/Sparks/Crafting exchanges, Title Broker, Cosmetic Shop, Daily and Hunt boards, Unity, Casino, Mystery Mog, Chocobo Derby, Race Changer, Prime Armory, Relic Forge, Augment Moogle and Sage, mastery trainers, Apex Trials, Gauntlet, Colosseum, Endless Tower, Test Dummy, HTBF / Infamy / Voidwatch vendors.' }, { title = 'HNMs and announcements', note = '• Dragon\'s Aery kings plus King Arthro and Serket keep a hybrid timed / QM spawn.\n• Behemoth, King Behemoth, Adamantoise, Aspidochelone, Roc and Simurgh have no retail spawn; the in-zone versions are Affinity NM copies.\n• Server-wide broadcasts for the first death, first job to each level, and first kills of tracked HNMs; winners are stored permanently.' }, { title = 'Background systems', note = '• Abyssea: permanent Visitant status on entry.\n• Homepoints fully restore HP and MP.\n• Zone-in mission/quest cutscenes are skipped but their effects still apply; talk to the NPC to view them.\n• Stuck event states clear on zoning or relogging (also fixes the Mog House 2F loop).\n• Bastok, Windurst and San d\'Oria regional NPCs are always present.\n• Finishing Zilart unlocks Mog Wardrobe 3.\n• New characters join a server linkshell; logins are announced.\n• First job to 99 is timestamped once for the Fastest 1 → 99 leaderboard.\n• Chocobo raising: chick in 2 days, riding speed cap 120.\n• Bastok quest Wish Upon a Star no longer needs its weather.\n• Seekers of Adoulin missions need no Imprimatur or fame.\n• Garrison runs with placeholder NPC data.' }, { title = 'Unchanged from retail', note = '• Mob HP, accuracy, damage and movement speed.\n• AH fees, enmity cap 30,000, Sneak/Invisible/Deodorize durations.\n• Modern cure and magic damage formulas.\n• Fishing is disabled server-wide.\n• Page dated 2026-08-28 05:00 PDT.' }, { title = 'Subjob EXP Share', note = '• Subjob is full level (99 main allows 99 sub) via SUBJOB_RATIO = 3.\n• 25% of every EXP gain (kills, FoV/GoV, ROE, scripted) is banked to the current subjob on top of main EXP.\n• Sub levels cost the same EXP as main levels; one big gain can clear several sub levels, with full stat recalculation.\n• Sub never exceeds main\'s level; banking stops while capped and resumes when main levels.\n• Bank is stored in SubExpBank and SubExpBankJob; check with !checkvar or ask staff.\n• Changing subjob resets the bank to 0 (except the very first gain under the system).\n• Works solo, in a party or with Trusts; raise EXP does not count; in merit mode the sub still gets its share.\n• Page dated 2026-09-07 15:15 PDT.' }, { title = 'Death Penalty', note = '• Applies only in Escha ZiTah: each death costs 10 Hunt Marks.\n• Exempt until you have 50 total NM kills; balance cannot go below zero.\n• A Death\'s Pardon from the Mystery Mog cancels one penalty and is used up.\n• Page dated 2026-07-12 21:15 PDT.' } } },
    { name = 'Gear and drops', group = 'Server', desc = 'How this server\'s item stats differ from retail, plus the custom Reforge armor upgrades and the Weapon Forge paths. Source: https://ffxi-legendary.com/reference/gear-vs-retail/, https://ffxi-legendary.com/progression/reforge/, https://ffxi-legendary.com/progression/weapon-forge/', steps = { { title = 'Gear vs Retail', note = '• Server item stats are checked against retail data from FFXIAH.com, refreshed about once a month.\n• Three lists: stats missing or lower on the server, stats with a different value, and stats only the server has (deliberate buffs).\n• Some \'missing\' rows are LSB implementation choices, e.g. Damage taken stored as separate physical/ranged mods.\n• Snapshot: 3169 items compared, cache date 2026-07-01; 2927 missing/lower, 3952 different, 1055 server-only stats.' }, { title = 'Gear vs Retail: Stats Missing or Lower on Server', note = '• Most gaps come from upstream LSB, which has no stat data for many il119 items (Arke set, Ajax, Angantyr).\n• Homestead Bow, Bowgun, Cesti and Gun: no TP Bonus (retail +1000).\n• Hashishin Tayt +1/+2/+3: no TP Bonus (retail +700/+750/+800); Nukumi Manoplas +1/+2/+3: none (retail +600/+650/+700); Enticer\'s Pants: none (retail +650).\n• Final Sickle: no HP (retail +250 / +200); Suit of Adamantite Armor: no DEF +200 or HP +182; Sacro Breastplate: no HP +182 or DEF +170.\n• Clemency, Grace, Mercy, Revelation, Perfection, Hope, Duty, Magnificent and Justice body/legs/head pieces lack roughly 153-187 DEF.\n• Cohort Cloak: no Magic Evasion (retail +156).\n• About 800 entries in total on the source page.' }, { title = 'Gear vs Retail: Stats with Different Values', note = '• Skormoth Mask: Triple Attack +400% on server vs +4% retail.\n• Apogee Crown / +1: HP +100 / +110 on server vs -100 / -110 retail.\n• Voluspa weapons are far weaker: Knuckles Accuracy/Attack +22 (retail +120); Bow and Gun Ranged Acc/Atk +22 (retail +100); other Voluspa weapons +10 to +25 (retail +80).\n• Vitiation Chapeau +3/+4: MP +7/+8 (retail +77/+87); Spaekona\'s Gloves: Evasion +10 (retail +82), MP +62 (retail +116).\n• Pitre Churidars +3/+4: HP +133/+146 (retail +67/+77).\n• Shields carry about half the retail DEF: Priwen 65 (130), Adapa 63 (126), Rinda 62 (124), Culminus 60 (120), Beatific Shield +1 56 (112).\n• About 790 entries in total on the source page.' }, { title = 'Gear vs Retail: Server-Only Stats (Custom Buffs)', note = '• Onca Suit DEF +428; Duban HP +300; Crepuscular Cloak DEF +264 and Magic Attack Bonus +85.\n• Lugra Cloak / +1 DEF +225 / +226; Respite Cloak DEF +219; Cohort Cloak / +1 DEF +217 / +218.\n• Espiritus Magic Attack Bonus +120; Idris MP +100; Tokko Chopper HP +95; Tokko Claymore and Lance HP +85; Tokko Staff MP +85.\n• Extra Evasion / Magic Evasion (about +80 to +157) on pieces such as Lethargy Houseaux +3, Nyame Sollerets and Gauntlets, Beckoner\'s Doublet +2/+3, Peltast\'s Cuissots +2/+3, Karagoz Scarpe +3 and Cappello +2/+3.\n• About 800 entries in total on the source page.' }, { title = 'Reforge System', note = '• Custom system that upgrades base AF, Relic and Empyrean armor up to +3 by hunting NMs.\n• Type !reforged to warp to the hub, pop an NM at a Spawner station, collect base pieces and marks, then upgrade at the Reforge Vendor.\n• The cap here is +3; AF and Relic +4 is made separately at the Dynamis-Divergence Forge from a reforged +3 piece plus [D]-zone materials. Empyrean has no +4.' }, { title = 'Reforge System: How it works', note = '• AF track: Sky Gods NMs, AF Marks. Relic track: Unity NMs, Relic Marks. Empyrean track: Abyssea NMs, Empyrean Marks.\n• Each kill gives one base piece from that track plus marks.\n• A drop has a 50% chance to be for your main job (chat shows \'(main-job match!)\'); otherwise it is a random piece for any job.\n• Vendor trades: base + marks for +1, +1 + marks for +2, +2 + marks for +3.\n• All Reforge NMs are level 99; tiers I-V differ by custom HP, stats and mechanics.\n• Plan on about 50-80 kills for a full 5-piece +3 set on one job.' }, { title = 'Reforge System: NPC locations', note = '• Hub: Diorama Abdhaljs-Ghelsba (warp with !reforged).\n• One Reforge Vendor and Mark Exchange stand at the hub entrance.\n• 8 NM Spawner stations, each with its own single-party lock, so several parties can farm at once.\n• Spawner 1 (-0.66, 0.00, -3.10); 2 (16.64, -0.54, 52.22); 3 (-26.16, 0.28, 94.49); 4 (-177.8304, -9.5338, 130.8604).\n• Spawner 5 (-97.7796, -10.6459, 129.2578); 6 (-102.6235, -10.0218, 76.0994); 7 (-116.3222, -10.0000, 22.8616); 8 (-168.8672, -10.1399, 60.9496).' }, { title = 'Reforge System: NM pools and rewards', note = '• Marks per kill by tier: I 60, II 80, III 100, IV 125, V 150 (all Lv99).\n• AF (Sky Gods, AF Marks): Genbu I, Suzaku II, Seiryu III, Byakko IV, Kirin V.\n• Relic (Unity NMs, Relic Marks): Bukhis I, Khun II, Padfoot III, Glavoid IV, Tinnin V.\n• Empyrean (Abyssea NMs, Empy Marks): Aello I, Iratham II, Briareus III, Itzpapalotl IV, Hadhayosh V.' }, { title = 'Reforge System: Combat behavior', note = '• NMs use their family TP moves plus a custom I-V mechanics profile; accuracy is tuned against level-99 augmented gear.\n• Sky Gods keep elemental additional damage and their TP/regain behavior; Genbu gains attack as HP drops.\n• Iratham swaps spell lists by phase; Briareus follows Mercurial Strike cues; Tinnin loses and regrows heads and chains breaths.\n• Padfoot, Khun and Aello use the Sheep, Caturae and Harpeia skill lists.' }, { title = 'Reforge System: Upgrade costs', note = '• Same on all three tracks: base to +1 costs 300 marks, +1 to +2 costs 900, +2 to +3 costs 2000.\n• Pay with the marks of that piece\'s track.' }, { title = 'Reforge System: Per-job set names', note = '• Format: job AF / Relic / Empyrean.\n• WAR Pummeler\'s / Agoge / Boii; MNK Anchorite\'s / Hesychast\'s / Bhikku; WHM Theophany / Piety / Ebers; BLM Spaekona\'s / Archmage\'s / Wicce.\n• RDM Atrophy / Vitiation / Lethargic; THF Pillager\'s / Plunderer\'s / Skulker\'s; PLD Reverence / Caballarius / Chevalier\'s; DRK Ignominy / Fallen\'s / Heathen\'s.\n• BST Totemic / Ankusa / Nukumi; BRD Brioso / Bihu / Fili; RNG Orion / Arcadian / Amini; SAM Wakido / Sakonji / Kasuga.\n• NIN Hachiya / Mochizuki / Hattori; DRG Vishap / Pteroslaver / Peltast\'s; SMN Convoker\'s / Glyphic / Beckoner\'s; BLU Assimilator\'s / Luhlaza / Hashishin.\n• COR Laksamana\'s / Lanun / Chasseur\'s; PUP Foire / Pitre / Karagoz; DNC Maxixi / Horos / Maculele; SCH Academic\'s / Pedagogy / Arbatel.\n• GEO Geomancy / Bagua / Azimuth; RUN Runeist / Futhark / Erilaz.\n• Page dated 2026-08-29.' }, { title = 'Weapon Forge', note = '• Five first-time weapon paths: Relic, Empyrean, Mythic, Aeonic and Prime.\n• Type !forgegates to see met (✓) and unmet (✗) requirements for every path; add a category to narrow it, e.g. !forgegates aeonic.\n• Obtain the base weapon from its source content, then forge it through three stages to its final form.' }, { title = 'Weapon Forge: Native Weapon-Skill Enhancement', note = '• Final-stage Relic, Empyrean, Mythic and Aeonic weapons boost their signature WS (60 WSs tuned individually), scaled from Prime\'s +200% benchmark.\n• Relic +100% (x0.50); Empyrean +120% (x0.60); Mythic +140% (x0.70); Aeonic +160% (x0.80).\n• Hit count, damage type, crit rules and utility effects stay the same; only damage rises.\n• Final Prime weapons: their 14 native WSs get +300% WS damage and may exceed the 999,999 damage cap.\n• Prime per-WS ceilings: Support (WHM, BLM, PLD, SMN, PUP, SCH, GEO) 1,499,999; Hybrid (RDM, BRD, BLU, COR, DNC, RUN) 1,749,999; Damage (WAR, MNK, THF, DRK, BST, RNG, SAM, NIN, DRG) 1,999,999.\n• A shared WS used from a non-Prime weapon is unaffected.\n• Page dated 2026-09-10.' } } },
    { name = 'Crafting and gathering', group = 'Server', desc = 'Item level 100+ equipment that crafters can make on this server, including lines found nowhere else. Source: https://ffxi-legendary.com/economy/crafted-gear/', steps = { { title = 'Crafted Gear', note = '• 4,603 synthesis recipes are live; synthesis yields 447 pieces of item level 100+ equipment.\n• Craft-only lines include Raetic, Arasy, Was, Oshosi and the job staves.\n• Retail escutcheon-master recipes are open to anyone at skill 110; the escutcheon key items are not required.\n• HQ versions come from the same recipe; crafted gear below level 99 is sold cheaply by the Auction House market-maker.' }, { title = 'How to craft', note = '• Level crafts the normal way; recipes match retail.\n• Guild NPCs sell low-tier ingredients; the Auction House market-maker stocks crystals and common materials.\n• Endgame recipes top out at skill 110.' }, { title = 'Item level 100+ craftables', note = '• Woodworking examples (all iLvl 119; +1 = HQ):\n• Ames / +1: Woodworking 110, Goldsmithing 110.\n• Animator P / +1 and Animator P II / +1: Woodworking 105.\n• Arasy Gun, Knife, Sainti / +1: Woodworking 110, Smithing 102. Arasy Staff / +1: Woodworking 102, Bonecraft 50.\n• Woodworking 110 + Alchemy 110: Archmage\'s Staff (HQ), Argute Staff (NQ), Draumstafir (HQ), Glyphic Staff (HQ), Kaumodaki (HQ), Kendatsuba Hakama, Jinpachi, Samue / +1.\n• Woodworking 110 + Smithing 110: Arke Crossbow (HQ), Dyrnwyn / +1.\n• Woodworking 110 + Goldsmithing 110 + Clothcraft 110: Asclepius (HQ), Bagua Wand (NQ), Bhima (HQ), Cleric\'s Wand (NQ).\n• Exalted Bow, Crossbow, Spear, Staff / +1: Woodworking 106.\n• The full 447-item table, all crafts, is on the source page.' } } },
    { name = 'Combat and skills', group = 'Server', desc = 'Server changes to weapon-skill damage and availability, plus purchasable cross-job abilities and traits and the Mastery Sigil upgrade system. Source: https://ffxi-legendary.com/reference/ws-vs-retail/, https://ffxi-legendary.com/progression/cross-job-abilities/, https://ffxi-legendary.com/progression/cross-job-traits/, https://ffxi-legendary.com/progression/spell-mastery/', steps = { { title = 'Weapon Skills vs Retail', note = '• Only two things differ from retail: the damage cap, and which weapon skills players can use.' }, { title = 'Weapon Skills vs Retail: Damage is uncapped for you and your pets', note = '• Retail caps any single hit at 131,071 because of the 17-bit damage packet.\n• Here the cap is removed for your WSs and melee, and for your pets, trusts, avatars and automatons.\n• The number shown over the mob still stops at 131,071; the real total is sent to you in chat, with pet/trust hits tagged, e.g. [Automaton WS] 250000.\n• Monster damage to players stays capped.\n• Several Prime weapons\' Aftermath adds Damage Limit +% (see Prime Armory).\n• Automatons get a small flat outgoing-damage multiplier to help against the server\'s level-150 NMs.' }, { title = 'Weapon Skills vs Retail: Weapon skills retail won\'t let you use', note = '• 16 monster-only WSs are usable by players wielding the matching Prime weapon (stock LSB leaves them commented out in sql/weapon_skills.sql).\n• Sarv (Archery, Prime Bow); Blitz (Axe, Prime Pickaxe); Dagda (Club, Prime Maul); Merciless Strike (Dagger, Mpu Gandring).\n• Disaster (Great Axe, Prime Great Axe); Tachi: Mumei (Great Katana, Kusanagi-no-Tsurugi); Fimbulvetr (Great Sword, Prime Blade).\n• Dragon Blow (Hand-to-Hand, Prime Fists); Maru Kala (Hand-to-Hand, Varga Purnikawa); Zesho Meppo (Katana, no Prime weapon listed).\n• Terminus (Marksmanship, Prime Gun); Diarmuid (Polearm, Prime Lance); Origin (Scythe, Prime Scythe); Oshala (Staff, Prime Staff).\n• Fast Blade II (Sword, Naegling); Imperator (Sword, Prime Sword).\n• fTP, hit counts, stat mods and skillchain properties follow stock LSB.\n• Page dated 2026-08-13.' }, { title = 'Cross-Job Abilities', note = '• The Cross-Job Ability Trainer is in the Utility cluster on Purgonorgo Isle.\n• Each ability is a permanent, per-character license costing 10,000,000 gil.\n• Abilities work on any main job with no subjob needed.' }, { title = 'Cross-Job Abilities: How It Works', note = '• Talk to the trainer and pick a job group (Warrior, Samurai, etc.).\n• Confirm the purchase; 10,000,000 gil is taken and the license is saved to your character.\n• Use the ability by macro: /ja "Ability Name" <me> (e.g. /ja "Meditate" <me>).\n• Bought abilities do not show in the in-game Job Abilities menu; macros are the only way to use them.\n• Normal recast timers apply.\n• Not sold: 2-hour abilities and pet/job-mechanic abilities (Sic, Ready, Rolls, Wyvern).' }, { title = 'Cross-Job Abilities: Available Abilities', note = '• 9 abilities across 4 job groups.\n• Named on the page: Meditate, Souleater, Berserk, Warcry, Rampart, Sentinel.\n• Effects listed include: attack up/defense down; accuracy up/evasion down; party-wide attack boost; party-wide crit rate boost; counter chance while standing; accuracy and Subtle Blow scaling with nearby allies; evading the next attack; HP-to-melee damage at an HP cost.\n• Page dated 2026-07-12.' }, { title = 'Cross-Job Traits', note = '• The Cross-Job Trait Trainer stands next to the Ability Trainer on Purgonorgo Isle.\n• Each trait costs 10,000,000 gil once per character and is permanent.\n• Traits are passive on every job, need no macro, re-apply on login and zoning, and stack with gear.\n• Dual Wield: any job can dual wield (+15% dual wield).\n• Counter: +5% counter chance.\n• Fast Cast: +15%.\n• Attack Bonus: +10% melee attack.\n• Page dated 2026-07-10.' }, { title = 'Spell & Skill Mastery', note = '• The Mastery Sage on Purgonorgo Isle sells permanent WS and magic upgrades for Mastery Sigils.\n• Type !empower to see your Sigil balance, owned upgrades and which rotation NMs are live.' }, { title = 'Spell & Skill Mastery: Mastery Sigils', note = '• Daily rotation: 3 target NMs live at once from a pool of 18; each kill gives 50 Sigils, once per target per rotation, shared by party members in the same zone.\n• Any other NM kill gives 2 Sigils, rising with mob level to a maximum of 10.\n• Pool: Jaggedy-Eared Jack (West Ronfaure), Bigmouth Billy (East Ronfaure), King Arthro (Jugner Forest), Lumber Jack (Batallia Downs), Stray Mary (Konschtat Highlands), Carnero (South Gustaberg).\n• Serpopard Ishtar (Tahrongi Canyon), Old Sabertooth (Sauromugue Champaign), Bastet (The Sanctuary of ZiTah), Voluptuous Vilma (Yuhtunga Jungle), Powderer Penny (Yhoator Jungle), Kraken (Qufim Island).\n• Nue and Gargantua (Beaucedine Glacier), Koenigstiger (Xarcabard), Stolas and Kreutzet (Cape Teriggan), Guivre (Kuftal Tunnel).' }, { title = 'Spell & Skill Mastery: Upgrades', note = '• Weapon Skill Potency: +8% WS damage per tier, up to Tier 5.\n• Spell Potency: per tier +6 Magic Attack, +8 magic damage, +5% cure potency, up to Tier 5.\n• Potency tiers stack and cost 15 / 30 / 55 / 90 / 140 Sigils.\n• WS proc Empowered Strike: per tier +8% chance a WS crits for +60% damage; Tiers 1-5 cost 20 / 40 / 70 / 110 / 160 Sigils; active immediately.\n• Trait riders cost 40 Sigils each and are permanent.\n• WS riders: Store TP +10; WS Accuracy +20; Crit Rate +6%; Crit Damage +10%; TP Saver (20% chance a WS uses no TP); Double Attack +5%.\n• Spell riders: Fast Cast +10%; Conserve MP +20; Magic Accuracy +20; Regain +2% per tick; Enhancing duration +20%; spell interruption resistance +20% SIRD.' }, { title = 'Spell & Skill Mastery: Checking your status', note = '• !empower lists your Sigil balance, owned potency tiers, trait riders and proc effects.\n• Page dated 2026-09-03.' } } },
    { name = 'Travel and quality of life', group = 'Server', desc = 'Warp commands, automatic character setup, convenience systems and the Purgonorgo Isle home point crystal on this server. Source: https://ffxi-legendary.com/reference/travel-and-warps/, https://ffxi-legendary.com/progression/server-features/, https://ffxi-legendary.com/changes/background-systems/, https://ffxi-legendary.com/economy/home-point/', steps = { { title = 'Travel and Warps', note = '• !warp opens a travel menu sorted by category; use it when you don\'t know the direct command.\n• Hub: main service hub. Home Point: your current home point.\n• Hunting League: hub plus the Rank I–V hunt clusters.\n• EXP Camps: camps by level band, 10 to 99. Capacity Camps: post-99 Capacity Point camps.\n• Activities: Battlefields, progression hubs, Unity, Domain, Wave Master, Ascension and other special travel.\n• Direct shortcuts: !hub, !expcamp, !hunt or !huntwarp, !capacity, !augwarp <stat> (catalyst zone), !home.\n• Page dated 2026-08-27.' }, { title = 'Always-Popped NMs', note = '• All Reisenjima Sanctorium NMs spawn at server start and come back 30 seconds after dying; no pop items or key items needed.\n• Abyssea NMs are popped at their ??? using Hunt Marks.\n• Reisenjima field NMs use Geas Fete.\n• Escha - Zi\'Tah and Reisenjima Henge use Hunting League spawner NPCs (!hunt) and are not on the auto-pop list.\n• Overworld augment-affinity bosses are a separate roster (Affinity NMs).' }, { title = 'Open World Mob Scaling', note = '• Normal mobs of level 91+ in 26 open-world progression zones (Apex/Locus camps, Adoulin fields, Escha and Reisenjima trash) get minimum stat floors on spawn; stronger mobs keep their own stats. NMs and dynamic pops are excluded.\n• 91–99: HP 60,000; Atk 600; Def 500; Acc 450; Eva 400.\n• 100–109: HP 100,000; Atk 800; Def 650; Acc 550; Eva 500.\n• 110–119: HP 180,000; Atk 1,100; Def 850; Acc 700; Eva 650.\n• 120–129: HP 320,000; Atk 1,500; Def 1,100; Acc 850; Eva 800.\n• 130–134: HP 450,000; Atk 1,800; Def 1,300; Acc 950; Eva 900.\n• 135+: HP 600,000; Atk 2,100; Def 1,500; Acc 1,050; Eva 1,000.\n• Mob magic accuracy uses the engine\'s normal above-99 scaling.' }, { title = 'Damage Cap and Combat Scaling', note = '• No single action can deal more than 999,999 damage to one target, for players and monsters alike.\n• Custom weapon skill bonus grows linearly with job points spent: x8 at fresh 99 to x13 at full mastery (2,100 JP). Pet weapon skills: x7 to x11.\n• Weapon skill damage cap: 79,999.\n• Nuke multipliers (fresh 99 / mastered): Elemental high x8/x13, mid x6/x10, low x4/x7; Ninjutsu x5/x8; Divine x5/x9; Blue Magic damage x1/x1. Drains, enfeebles, DoT and Helix spells are not boosted.\n• Nuke cap 79,999, higher with a Relic/Mythic/Empyrean or Prime weapon.\n• Final-tier Ambuscade weapons: +10% weapon skill damage (110%) and a 99,999 weapon skill cap.\n• Below 99 there is a 3-level grace band; outleveling a target beyond it shrinks the bonus and costs 8 weapon skill accuracy per level of difference.' }, { title = 'Automatic Character Setup', note = '• Applied to every new character on first login, no NPC needed.\n• Grants: all weapon skills, all job-appropriate spells, skills capped to level, all Trusts, all quests marked complete, all maps, all Outpost Warps and conquest points, all Homepoints and Survival Guides, maximum Wardrobe slots.\n• Blue Mage gets all 195 learnable blue spells automatically at the right level (also as /BLU); login runs a catch-up. You still set your own spells.' }, { title = 'Healing, Buffs and EXP', note = '• Touching any Homepoint crystal fully restores HP and MP.\n• !buff (anywhere): regional buff for your zone (Signet, Sanction, Sigil or Ionis), Refresh 10% max MP/tick, Regen 10% max HP/tick, Regain scaling with level, Composure. Handy right after zoning or login.\n• Zoning into Escha - Zi\'Tah (!hunt) applies the same buff package automatically.\n• Subjob earns 25% (0.25x) of main job EXP automatically; the bank is per subjob and does not transfer when you switch.\n• Enhancing Magic durations are doubled after all other modifiers (gear, RDM merits/JP, Composure, Perpetuance, Embolden). Example: 5-minute Protect lasts 10 minutes.' }, { title = 'Hub NPCs (Purgonorgo Isle, !hub)', note = '• Mystery Mog: gil gacha with standard and premium pulls; prizes range from cure items to Hunt Mark jackpots and Ascension Points. Meant as a gil sink.\n• Gil Exchange: 2,000,000 gil = 5 Hunt Marks; 40,000,000 = 100; 200,000,000 = 500.\n• Title Broker: sells cosmetic titles for gil at several price tiers; anyone may buy any title.' }, { title = 'Auction House', note = '• Always stocked with every non-iLevel weapon, armor and accessory; open it anywhere with !ah.\n• Prices by equip level: 1–10 14,000; 11–20 17,000; 21–30 21,000; 31–40 26,000; 41–50 33,000; 51–60 41,000; 61–70 51,000; 71–75 64,000; 76–90 80,000 gil.\n• The server buys back such gear at 50% of table price: list it at or under that price and payment arrives in your delivery box on the hourly pass.\n• Item level 119 gear is sold by the Gear Vendors, not the AH.' }, { title = 'Stuck States and Cutscenes', note = '• A watchdog checks you 3 seconds after zoning into any of the 10 starting-city zones (Southern/Northern/Port San d\'Oria, Bastok Mines, Bastok Markets, Port Bastok, Windurst Waters, Windurst Walls, Port Windurst, Windurst Woods) and clears a stuck event flag.\n• It also sets the Mog House second-floor unlock flag to stop the flower-quest cutscene loop.\n• If stuck in a loop: zone into, or log out and back in inside, a starting city and wait briefly.\n• Auto-play cutscenes on zone-in are skipped everywhere, but their effects (position, mission flags, key items) still apply. Talk to the NPC to view one.' }, { title = 'Other Server Changes', note = '• Abyssea: permanent Visitant status on entry (including via !abyssea), no timer or Traverser Stones.\n• Chocobo raising: chick at 2 days, adolescent at 7, adult at 14; riding speed cap 120; up to 60 minutes riding.\n• Seekers of Adoulin missions skip the Imprimatur and fame check.\n• Conquest regional merchants in Port Bastok, Southern San d\'Oria and Windurst Woods always appear (Nokkhi Jinjahl, Ominous Cloud, Valeriano, Mokop-Sankop, Cheh Raihah, Nalta, Dahjal).\n• Al Zahbi: every kill drops one extra random item from the whole item database.\n• GM Home kills drop Gear Vendor seals: below level 90 Beastmens Medals, 90+ Kindreds Medals, NMs one tier up (90+ NM = Demons Medals). At least 1 per kill; 50% for 2+, 33% for 3+, 25% for 4+, 5% for 10.\n• Server-wide broadcasts for world firsts (first death, first level up and down, first of each job to 10/20/30/40/50/60/70/75/80/90/99, first kill of each NM) and player logins; firsts persist across restarts.' }, { title = 'Home Point Crystal (Purgonorgo Isle)', note = '• Found in the services area of Purgonorgo Isle (!hub); always free, no attunement required.\n• Choose Set home point here to make the isle your return point after being raised or using a home-point warp.\n• Choose Warp to a home point, pick a region, then a destination; use Next and Prev on long lists.\n• 121 destinations in 12 regions: San d\'Oria 11, Bastok 12, Windurst 15, Jeuno 10, Aht Urhgan 5, Adoulin 4, Ulbuka 7, Other Towns 10, Past [S] 6, Sky 6, Sea 5, Dungeons & Fields 30.' } } },
    { name = 'Commands', group = 'Server', desc = 'Selected player chat commands (prefix !) available on this server; the source lists 111 player commands, 91 of them custom. Source: https://ffxi-legendary.com/reference/commands/', steps = { { title = 'Overview', note = '• Type commands in any chat channel with the ! prefix; no GM rank needed.\n• 111 player commands in total, 91 custom to this server. GM-only commands are not listed.\n• !help shows a categorized command menu.' }, { title = 'Movement & Teleport', note = '• !home: go to your homepoint.\n• !hub: go to the main hub.\n• !warp: travel menu.\n• !unitywarp <string>: Unity warp.\n• !pos: show your current position (does not move you).\n• !augwarp <stat>: go to a zone dropping a catalyst for that augment stat, e.g. !augwarp Haste.\n• !capacity: Bibiki Bay (default); !capacity bibiki = Bibiki Bay; !capacity ranperre = King Ranperre\'s Tomb; !capacity ronfaure or !capacity3 = East Ronfaure [S] north square; !capacity 4 or !capacity4 = East Ronfaure [S] south square.\n• !expcamp, !diwarp, !henge also exist (no description given).' }, { title = 'Items & Inventory', note = '• !ah: Auction House menu from anywhere.\n• !shop <string> <string>: shop command.\n• !catalysts: list augment catalysts banked at the Arcane Augmenter on the hub (drops go to the NPC, not your bags).\n• !dig: dig for the strongbox your treasure map marks; maps drop from Hunting League kills.' }, { title = 'Buffs & Power', note = '• !buff: regional buff (Signet/Sanction/Sigil/Ionis) plus Refresh, Regen, Regain, Composure and Reraise III.\n• Refresh: 10% max MP per tick under 99, flat +10 MP per tick at 99+.\n• Regen: 10% max HP per tick under 99, 3.5% at 99+.\n• Regain: 1 per 10 levels, minimum 1.\n• !autojp: spends all unspent job points on your current main job, evenly across categories.\n• !automerits: spends all unspent merit points evenly across categories.\n• !autoready <string>: toggle automatic Ready moves for BST jug pets.' }, { title = 'Information', note = '• !mystats: full dump of all your stats including gear and buffs, no target needed.\n• !getstats: print the cursor target\'s stats.\n• !augstats: real augment contributions on equipped gear.\n• !checkexpbonus: show your EXP_BONUS mod and its per-kill effect.\n• !achievements: earned and unearned personal milestones with rewards.\n• !events: active and upcoming seasonal bonus mark events with multiplier and dates.\n• !featured: Weekly Featured Hunt NM per Hunting League tier; first kill of the week gives 2x base marks, stacking with the First-Kill bonus.\n• !hades: today\'s five Hades objectives and which are ready; shards are paid at the Hades NPC.\n• !checkascend, !checkrebirth, !unity also exist.' }, { title = 'Content Helpers', note = '• !apex: check Apex Trials record and Paragon Points or quit a climb; start climbs at the Apex Arbiter NPC.\n• !empower: view Spell & Skill Mastery (Mastery Sigils, potency tiers, trait riders); buy upgrades from the Mastery Sage in Leafallia.\n• !fellow <string>: summon, dismiss or set the Adventuring Fellow\'s combat mode; upgrades at the Fellow Officer in zone 44.\n• !fellowstats and !fellowaudit: check the summoned Fellow\'s live stats against expected values.\n• Other listed commands without descriptions: !affinitynm, !ambuscade, !auginfo, !augment, !empyaby, !erenquest, !fellowname, !forgegates, !gauntlet, !geas, !geaski.\n• The rest of the command list is only on the source page.' } } },
    { name = 'Rules', group = 'Server', desc = 'Conduct rules, penalties and where to report issues on this server. Source: https://ffxi-legendary.com/rules/', steps = { { title = 'Summary', note = '• Bots, automation, speedhacks, wallhacks and packet editing are discouraged.\n• Windower or Ashita quality-of-life plugins (maps, chat filters, bag sorting, tooltips) are allowed; ask in Discord if unsure.\n• No harassment, hate speech, slurs or targeted toxicity; competitive trash talk is allowed.\n• Real-money trading of gil or items means a permanent ban with no appeal.\n• Multi-boxing is unlimited; there is no account cap.\n• Report bugs in #bugs on Discord; exploiting one before reporting earns strikes based on severity. Good-faith reports are rewarded.' }, { title = 'GMs', note = '• GMs do server maintenance only: no items, gil or gear, no spawning content on request, no stepping into normal competition, no teleports when stuck (use /heal or rezone).\n• Staff never ask for your password; report anyone who does as an impersonator.' }, { title = 'Consequences', note = '• Strike 1: warning. Strike 2: 24-hour ban. Strike 3: permanent ban.\n• Real-money trading, sustained harassment and large-scale exploiting go straight to a permanent ban.\n• Staff decisions are final, but bans can be appealed on Discord.' }, { title = 'Contact (Discord)', note = '• #bugs: bugs and exploits.\n• #questions: general questions.\n• #recommendations: suggestions.\n• #general: everything else, including Hall of Fame milestone submissions, ban appeals and account issues (or DM a GM).\n• Page dated 2026-07-05.' } } },
    { name = 'Recent changes', group = 'Server', desc = 'A condensed digest of the player-facing items in the latest server changelog entries; deploy stamps, crash internals and admin tooling are left out. Source: https://ffxi-legendary.com/changelog/', steps = { { title = 'Week of September 21–27, 2026', note = '• Kraken Club +1 now has a complete way to obtain it, and its nine materials show proper names in the client.\n• Tidewake was added.\n• Magic Barrier now works as an absorb pool that depletes as it takes damage.' }, { title = 'Week of September 14–20, 2026', note = '• Cosmic +1 IDs restored; finished Hades Steel weapons are sold; currency can be banked at a hub moogle; Community Naul added.\n• Custom DATs rebuilt so stub item IDs no longer crash the client.\n• Aeonic Maat fights as whatever job you enter with, using real spells, job abilities and weapon skills.\n• Eren requires a mastered Fellow transformation quest.\n• Dynamis single-currency drops pay 100/50/20/5 with a flat 5% chance at a 100-piece; Dreamland now matches the cities.\n• Weapon Forge banks matching Aeonic attestations; abandoned Dynamis [D] copies now fail.\n• Daily Hades spawns when the hub boots.\n• A server-wide announcement fires when someone completes a 119 III Relic, Empyrean, Mythic, Aeonic or Prime.\n• Weapon Forge and Repeat Relic Forge accept 100-piece and 10k-piece Dynamis currency mixed at 10:1.\n• Fighting targets 30+ levels above you now means a lethal hit (replaces the HP pulse); Abyssea party credit and HP scaling stay in-zone.\n• Ascension Omega and Provenance Watcher are no longer hidden; a Fellow named Eren can exceed the normal damage and tank limits.\n• Upgrade forges no longer leave the previous REMA/reforge tier on equipped gear; lower stages are removed at login.\n• Roaming mobs now react to spell hate.\n• Fixes: merit WS, Coronach, Lilisette, Specter Worm pilgrimage, Unity accolades on alts, AAHM warp, Raja magic at 60%.\n• Gastraphetes pilgrimage damage and augments restored; family-type pilgrimages count the mobs players actually hunt.\n• /BLU nukes nerfed; /THF trait TH restored under the 14/17 caps; Hades no longer sells mid-week.\n• Overlevel EXP abuse blocked.\n• Unique Apex and Unity Wanted spawns no longer trigger world-first kill announcements.' }, { title = 'Week of September 7–13, 2026', note = '• THF: Larceny stolen duration fixed (it used milliseconds instead of seconds); main-job Mug drains HP on a 90s timer; TH17 added.\n• Kamihr tiger clones link with the retail tigers; magic splash caps added.\n• Dynamis 100-piece rates raised; ascension reduced to 300 marks; a second Hades Steel and Mail stall opened.\n• Hades: silent second form sells weekend wares; six weekend stalls opened; Crate currency can be banked on Hold.\n• Unity Wanted rewards always grant the maximum of their "Unity Ranking" stat.\n• Zvahl Baileys: 43 trash mob groups restored.\n• Legendary Launcher page published; rescue option sends players to Lower Jeuno.\n• Trust healers that stand back now park on the summoner.\n• Gauntlet: saved jobs can rematch earlier NMs; Pandemonium Warden silence eased.\n• Forge: one REMA repeat credit per family; Relic/Empyrean/Mythic fTP lowered so 999k remains the Aeonic ceiling.\n• Odyssey 119s added to Weighted Steel with WS capped at 349k.\n• Pre-Prime weapon skill damage capped at 999k.\n• Goldpiece fix, Geas shop reduction, Hades daily, Kraken Club +1, Geas Beitetsu and Dynamis 100-pieces shipped.\n• Divergence no longer splits a party across two [D] copies; !warpty no longer re-binds members already in another copy.\n• \'Phys DT II\' / \'Magic DT II\' augments now use the tier-II modifiers.\n• (More lines on the source page.)' }, { title = 'Week of August 31 – September 6, 2026', note = '• Abyssea first-pop delay fixed; party HP reduced to 4x; swing reset changed.\n• Expcamp curve, combat speed, pilgrimage and Ambuscade changes landed.\n• Pets match the master\'s run speed.\n• HTBF airship parties start on the deck.\n• Sylvie keeps dual-bubble; GEO icons show on the status bar.\n• Cheap BLU spells cost more; BLU heals scale with investment.\n• Multiple map crash fixes (Dynamis [D], Reforge NMs, inventory sort, trusts, Wild Card).\n• (More lines on the source page.)' }, { title = 'Week of August 24–30, 2026', note = '• Blue Mage set traits made retail-correct; BLU spells repaired and retuned.\n• Hunt NMs converted to visible 30-minute camps; missing camps spawned; Reforge camps expanded.\n• Public chat locked until your highest job reaches level 10.\n• Kraken Club reset to farm-only numbered drops.\n• Leftover gear vendors closed; Sparks vendors no longer sell equipment; Dark Seal menus restored; Judge gear restored.\n• Legendary Ring removed from random loot; Rem\'s Tales and Vigil weapons removed from live loot.\n• Affinity HNMs have retail loot and spawn at retail locations; Geirskogul restored.\n• Crystallization is all-or-nothing; Maat\'s Cap has a five-slot lock.\n• Purchased cross-job abilities remain usable after a job change.\n• Hunt Gold weapons and accessory tiers restocked; Hunt Rank IV pays 75 marks.\n• HTBF victories, airship staging and mob names completed.\n• (More lines on the source page.)' }, { title = 'Week of August 17–23, 2026', note = '• Blood Pact recast lowered to 20s native with a 6s floor.\n• BST strengthened; HTBF entry simplified and restored; physical Ready restored.\n• Companion progression overhauled, including companion equipment, PUP automaton merit tracking and pet skills in the Ready menu.\n• Battlefield and pilgrimage credit restored.' } } },
}

return S
